    SHOW = 'MainBattleChapterRewardPopup_Under_Cell_Show',
    WAIT = 'UI_Common_List_Cell_Wait_1',
}

local Pos_With_Reward = Vector2.New(87, -2)
local Pos_Without_Reward = Vector2.New(-6, -23)

--- from: Assets/BundleResources/Prefabs/BattleSelection/MainBattleChapterRewardPopup.prefab > name: Cell
