local UIMainBattleChapterRewardPopupNode = Class('UIMainBattleChapterRewardPopupNode')

function UIMainBattleChapterRewardPopupNode:__init()
    self._data = nil
    self._fishPlaceId = nil
    self.goodsId = nil
    self.effectStart = nil
    self.cb = nil
    self.position = nil
    self.maxChapterNo = 0
    ---@type UnityEngine.Transform
    self.redPointTrans = nil
end

function UIMainBattleChapterRewardPopupNode:__delete()
    self._data = nil
    self.goodsId = nil
    self._fishPlaceId = nil
    self.position = nil
    self.effectStart = nil
    self.maxChapterNo = 0
    self.redPointTrans = nil
    self.cb = nil
end

function UIMainBattleChapterRewardPopupNode:Awake()
    self.redPointTrans = self.controller.transform:Find("Root/redPoint")
    SetButtonAction(self.controller.transform:Find("Root"), function()
        ---点击无素
        if self.cb then
            self.cb(self._data, self.position)
        end
    end)
    self:PlayAnimByHide()
end

function UIMainBattleChapterRewardPopupNode:SetRedPoint(position, visibility)
    if self.redPointTrans then
        visibility = checkBool(visibility)
        CfUtils.SetActive(self.redPointTrans, visibility)
        if visibility then
            local rectTransform = KTool.GetComponent(self.redPointTrans.gameObject, typeof(RectTransform))
            rectTransform.anchoredPosition = position
        end
    end
end

function UIMainBattleChapterRewardPopupNode:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.controller, CELL_ANIM_NAME.IDLE)
end


function UIMainBattleChapterRewardPopupNode:PlayAnimByHide()
    CfUtils.PlayAnimation(self.controller, CELL_ANIM_NAME.HIDE)
end

function UIMainBattleChapterRewardPopupNode:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.controller.gameObject, delayIndex, CELL_ANIM_NAME.SHOW, CELL_ANIM_NAME.WAIT)
end

---Refresh
---@param data ChapterVo
---@param goodsId string 是否是自己
---@param effectStart string 是否是自己
---@param position string 是否是自己
---@param maxChapterNo string 是否是自己
function UIMainBattleChapterRewardPopupNode:Refresh(data, goodsId, effectStart, position, maxChapterNo)
    self.goodsId = string.split(goodsId, ";")
    self.effectStart = effectStart
    self.position = checkNumber(position)
    self.maxChapterNo = checkNumber(maxChapterNo)
    if not data then
        return
    end
    self._data = data
    self:FillSelf()
end

---SetSelected
---是否设置选中的状态
---@param isSelected boolean
function UIMainBattleChapterRewardPopupNode:SetSelected(isSelected)
    isSelected = checkBool(isSelected)
    CfUtils.SetActive(self.StatusSelect, isSelected)
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(self._data.id)
    CfUtils.SetUISwitchText(self.TextNumber, (isSelected and isUnlock) and 2 or 1)
    CfUtils.SetActive(self.ImgLock, not isUnlock)
    if isUnlock then
        CfUtils.SetUISwitchImage(self.ImgBg, isSelected and 4 or 3)
    else
        CfUtils.SetUISwitchImage(self.ImgBg, isSelected and 2 or 1)
    end
end

function UIMainBattleChapterRewardPopupNode:SetCallbackAction(cb)
    self.cb = cb
end

function UIMainBattleChapterRewardPopupNode:FillSelf()
    CfUtils.FillText(self.TextNumber, string.format("%0.2i", self._data.number))
    ----是否已领取过
    local isDrawFinish = QuestConfMgr:GetInstance():IsDrawChapterReward(self._data.id)
    CfUtils.SetActive(self.RewardTips, checkNumber(self._data.headRewardId) > 0 and not isDrawFinish)
    CfUtils.SetActive(self.Finish, isDrawFinish)
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(self._data.id)
    local isCanDraw = QuestConfMgr:GetInstance():IsCanDrawChapterReward(self._data.id)
    local position = checkNumber(self._data.headRewardId) > 0 and Pos_With_Reward or Pos_Without_Reward
    if checkNumber(self._data.number) == self.maxChapterNo then
        position = Pos_Without_Reward
    end
    self:SetRedPoint(position, isCanDraw and isUnlock)
    if checkNumber(self._data.headRewardId) > 0 and not isDrawFinish then
        if checkNumber(self._data.number) == self.maxChapterNo then
            CfUtils.SetActive(self.RewardTips, false)
        else
            CfUtils.SetActive(self.RewardTips, not isDrawFinish)
            local playerHeadNode = self.RewardTips:Find("CommonPlayerHeadNode")
            if playerHeadNode and not isDrawFinish then
                ---@type CommonPlayerHeadNode
                local headEnv = CfUtils.GetLuaScr(playerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
                if headEnv then
                    headEnv:SetCallBack(function()
                        ---点头像的回调
                        if self.cb then
                            self.cb(self._data, self.position)
                        end
                    end)
                    ---@type GoodsVo
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.headRewardId)
                    if goodsVo then
                        --种类区分：1头像2头像框3徽章4主题
                        if checkNumber(goodsVo.kind) == 1 then
                            headEnv:FreshHeadIcon(goodsVo.id, true)
                        elseif checkNumber(goodsVo.kind) == 2 then
                            headEnv:FreshFrame(goodsVo.id, true)
                        end
                    else
                        CfUtils.SetActive(self.RewardTips, false)
                    end
                end
            end
        end
    end
    --local isDraw = QuestConfMgr:GetInstance():IsDrawChapterReward(self._data.id)
    --local isCanDraw = QuestConfMgr:GetInstance():IsCanDrawChapterReward(self._data.id)
    --
    --CfUtils.SetActive(self.FontStyleButton, isCanDraw)
    --CfUtils.SetActive(self.TxtOngoing, not isDraw and not isCanDraw)
    --CfUtils.SetActive(self.FinishGroup, isDraw)
    --
    --CfUtils.SetUISwitchImage(self.ImgInk1, isCanDraw and 2 or 1)
    --CfUtils.SetUISwitchImage(self.ImgInk2, isCanDraw and 2 or 1)
end

function UIMainBattleChapterRewardPopupNode:OnDrawReward()
    local isDraw = QuestConfMgr:GetInstance():IsDrawChapterReward(self._data.id)
    local isCanDraw = QuestConfMgr:GetInstance():IsCanDrawChapterReward(self._data.id)

    if isDraw then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    elseif not isCanDraw then
        GameUtils.Toast(localize("未满足条件"))
        return
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    comp:ChapterRewardDrawReq(self._data.id, function(rewards)
        Events.Broadcast(Constants.EventNames.MainQuestChapterRewardChange)
        for i, v in pairs(rewards) do
            for i, goodsId in pairs(self.goodsId) do
                if checkNumber(v.goodsId) == checkNumber(goodsId) then
                    GameUtils.StartFlyGoods(self.effectStart.gameObject, checkNumber(v.goodsId))
                end
            end
        end
        self:FillSelf()
    end)
end

function UIMainBattleChapterRewardPopupNode:OnDestroy()
    if self._co2 ~= nil then
        cs_coroutine.stop(self._co2)
        self._co2 = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainBattleChapterRewardPopupNode
